-- Process instance and token runtime columns. Same column order, checks, and comments as db/init/05_tables.sql.

ALTER TABLE app.process_instances ADD COLUMN IF NOT EXISTS start_element_id VARCHAR(64);
ALTER TABLE app.process_instances ADD COLUMN IF NOT EXISTS start_trigger_type VARCHAR(32);
ALTER TABLE app.process_instances ADD COLUMN IF NOT EXISTS start_event_id UUID;
ALTER TABLE app.process_instances ADD COLUMN IF NOT EXISTS subject_type VARCHAR(64);
ALTER TABLE app.process_instances ADD COLUMN IF NOT EXISTS subject_id UUID;

ALTER TABLE app.process_tokens ADD COLUMN IF NOT EXISTS wait_kind VARCHAR(32);
ALTER TABLE app.process_tokens ADD COLUMN IF NOT EXISTS wait_ref VARCHAR(128);
ALTER TABLE app.process_tokens ADD COLUMN IF NOT EXISTS assigned_user_id UUID REFERENCES app.users(user_id) ON DELETE SET NULL;
ALTER TABLE app.process_tokens ADD COLUMN IF NOT EXISTS assigned_group_id UUID REFERENCES app.groups(group_id) ON DELETE SET NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'chk_process_instances_start_trigger_type'
          AND conrelid = 'app.process_instances'::regclass
    ) THEN
        ALTER TABLE app.process_instances
            ADD CONSTRAINT chk_process_instances_start_trigger_type
            CHECK (
                start_trigger_type IS NULL OR start_trigger_type IN ('manual', 'event', 'schedule')
            );
    END IF;
END $$;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'chk_process_instances_subject_pair'
          AND conrelid = 'app.process_instances'::regclass
    ) THEN
        ALTER TABLE app.process_instances
            ADD CONSTRAINT chk_process_instances_subject_pair
            CHECK (
                (subject_type IS NULL) = (subject_id IS NULL)
            );
    END IF;
END $$;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'chk_process_tokens_wait_kind'
          AND conrelid = 'app.process_tokens'::regclass
    ) THEN
        ALTER TABLE app.process_tokens
            ADD CONSTRAINT chk_process_tokens_wait_kind
            CHECK (
                wait_kind IS NULL OR wait_kind IN ('manual', 'worker', 'timer', 'event')
            );
    END IF;
END $$;

COMMENT ON COLUMN app.process_instances.start_element_id IS
    'Start event element id in the frozen definition that created this instance.';
COMMENT ON COLUMN app.process_instances.start_trigger_type IS
    'How this instance was started: manual, event, or schedule.';
COMMENT ON COLUMN app.process_instances.start_event_id IS
    'Domain event UUID that triggered this instance when start_trigger_type is event. NULL otherwise.';
COMMENT ON COLUMN app.process_instances.subject_type IS
    'Optional business entity type linked to this instance (e.g. service_order, service_request). Must be paired with subject_id.';
COMMENT ON COLUMN app.process_instances.subject_id IS
    'Optional business entity UUID linked to this instance. Must be paired with subject_type.';
COMMENT ON COLUMN app.process_tokens.wait_kind IS
    'What a waiting token is waiting for: manual, worker, timer, or event. NULL when not waiting.';
COMMENT ON COLUMN app.process_tokens.wait_ref IS
    'Correlation reference or created entity/job id for a waiting token.';
COMMENT ON COLUMN app.process_tokens.assigned_user_id IS
    'Resolved assignee user UUID for a manual activity token. ON DELETE SET NULL.';
COMMENT ON COLUMN app.process_tokens.assigned_group_id IS
    'Resolved assignee group UUID for a manual activity token. ON DELETE SET NULL.';

CREATE OR REPLACE FUNCTION app.tgr_process_instances_guard_update()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    free_keys TEXT[] := ARRAY['started_by', 'updated_at'];
BEGIN
    IF NEW.process_id IS DISTINCT FROM OLD.process_id
       OR NEW.version_id IS DISTINCT FROM OLD.version_id
       OR NEW.started_at IS DISTINCT FROM OLD.started_at
       OR NEW.start_element_id IS DISTINCT FROM OLD.start_element_id
       OR NEW.start_trigger_type IS DISTINCT FROM OLD.start_trigger_type
       OR NEW.start_event_id IS DISTINCT FROM OLD.start_event_id
    THEN
        RAISE EXCEPTION 'process instance %: creation stamp is immutable', OLD.id USING ERRCODE = '23514';
    END IF;

    -- started_by may only be released to NULL (ON DELETE SET NULL when the user is deleted).
    IF NEW.started_by IS DISTINCT FROM OLD.started_by AND NEW.started_by IS NOT NULL THEN
        RAISE EXCEPTION 'process instance %: started_by can only be released to NULL', OLD.id USING ERRCODE = '23514';
    END IF;

    -- A terminal instance is frozen (history). Only the started_by release and updated_at may change.
    IF OLD.status <> 'running'::app.process_instance_status THEN
        IF (to_jsonb(OLD) - free_keys) IS DISTINCT FROM (to_jsonb(NEW) - free_keys) THEN
            RAISE EXCEPTION 'process instance %: instance is % and therefore frozen', OLD.id, OLD.status USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    -- An instance may become terminal only after all of its tokens are terminal.
    IF NEW.status <> 'running'::app.process_instance_status AND EXISTS (
        SELECT 1 FROM app.process_tokens t
        WHERE t.instance_id = OLD.id
          AND t.state IN ('ready'::app.process_token_state, 'waiting'::app.process_token_state, 'incident'::app.process_token_state)
    ) THEN
        RAISE EXCEPTION 'process instance %: cannot become % while it has active tokens', OLD.id, NEW.status USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION app.tgr_process_instances_guard_update() IS
    'BEFORE UPDATE on app.process_instances. Freezes process_id/version_id/started_at/start_element_id/start_trigger_type/start_event_id; allows started_by only to NULL; freezes terminal instances except started_by/updated_at; blocks becoming terminal while active tokens remain.';

-- Drop the denormalized procedure catalogs. The trigger drop is guarded because
-- DROP TRIGGER requires the table, and a re-run no longer has these tables.
DO $$
BEGIN
    IF to_regclass('app.process_system_procedures') IS NOT NULL THEN
        DROP TRIGGER IF EXISTS tgr_process_system_procedures_prevent_system_delete ON app.process_system_procedures;
    END IF;
    IF to_regclass('app.process_manual_procedures') IS NOT NULL THEN
        DROP TRIGGER IF EXISTS tgr_process_manual_procedures_prevent_system_delete ON app.process_manual_procedures;
    END IF;
    IF to_regclass('app.process_external_procedures') IS NOT NULL THEN
        DROP TRIGGER IF EXISTS tgr_process_external_procedures_prevent_system_delete ON app.process_external_procedures;
    END IF;
END $$;

DROP TABLE IF EXISTS app.process_system_procedures;
DROP FUNCTION IF EXISTS app.prevent_process_system_procedure_deletion();
DROP TABLE IF EXISTS app.process_manual_procedures;
DROP FUNCTION IF EXISTS app.prevent_process_manual_procedure_deletion();
DROP TABLE IF EXISTS app.process_external_procedures;
DROP FUNCTION IF EXISTS app.prevent_process_external_procedure_deletion();

-- ===========================================================================
-- Process procedure catalog (namespaces, objects, procedures)
-- ===========================================================================
-- Three levels, same shape as the events library (domain / object / type).
-- Rows are written only by init scripts and migrations
-- (db/init/17_process_procedures.sql). Namespaces and objects have no delete
-- trigger: ON DELETE RESTRICT on the foreign keys is their only protection.
-- System procedure rows are protected by tgr_process_procedures_prevent_system_delete.

CREATE TABLE IF NOT EXISTS app.process_procedure_namespaces (
    namespace_key VARCHAR(50) PRIMARY KEY,
    kind          VARCHAR(20) NOT NULL,
    name          JSONB NOT NULL,
    description   JSONB,
    is_system     BOOLEAN NOT NULL DEFAULT true,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_process_procedure_namespaces_key_format
        CHECK (namespace_key ~ '^[a-z][a-z0-9_]*$'),
    CONSTRAINT chk_process_procedure_namespaces_kind
        CHECK (kind IN ('module', 'connector')),
    CONSTRAINT chk_process_procedure_namespaces_name_localized
        CHECK (app.is_localized_text(name)),
    CONSTRAINT chk_process_procedure_namespaces_description_localized
        CHECK (description IS NULL OR app.is_localized_text(description))
);

COMMENT ON TABLE app.process_procedure_namespaces IS
    'Procedure namespace registry. A namespace is a module or a connector and is the first segment of a procedure key. Rows are written only by init scripts and migrations. Localized columns require english; russian is optional.';
COMMENT ON COLUMN app.process_procedure_namespaces.namespace_key IS
    'Primary key. First segment of object_key and of procedure_key. Must match ^[a-z][a-z0-9_]*$. Referenced by app.process_procedure_objects with ON DELETE RESTRICT, which is the only delete protection.';
COMMENT ON COLUMN app.process_procedure_namespaces.kind IS
    'Namespace kind: module for an application module, or connector for an external connector.';
COMMENT ON COLUMN app.process_procedure_namespaces.name IS
    'Localized display name. JSON object with required non-empty english and optional russian string. No other keys. Checked by app.is_localized_text.';
COMMENT ON COLUMN app.process_procedure_namespaces.description IS
    'Localized description of the namespace. NULL, or LocalizedText with required non-empty english and optional russian. Plain text.';
COMMENT ON COLUMN app.process_procedure_namespaces.is_system IS
    'True for platform-seeded namespaces.';
COMMENT ON COLUMN app.process_procedure_namespaces.created_at IS
    'Time the row was inserted by an init script or a migration.';

CREATE TABLE IF NOT EXISTS app.process_procedure_objects (
    object_key    VARCHAR(100) PRIMARY KEY,
    namespace_key VARCHAR(50) NOT NULL,
    object_name   VARCHAR(50) NOT NULL,
    name          JSONB NOT NULL,
    description   JSONB,
    is_system     BOOLEAN NOT NULL DEFAULT true,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_process_procedure_objects_namespace
        FOREIGN KEY (namespace_key) REFERENCES app.process_procedure_namespaces (namespace_key) ON DELETE RESTRICT,
    CONSTRAINT uq_process_procedure_objects_namespace_name
        UNIQUE (namespace_key, object_name),
    CONSTRAINT chk_process_procedure_objects_name_format
        CHECK (object_name ~ '^[a-z][a-z0-9_]*$'),
    CONSTRAINT chk_process_procedure_objects_key_match
        CHECK (object_key = namespace_key || '.' || object_name),
    CONSTRAINT chk_process_procedure_objects_name_localized
        CHECK (app.is_localized_text(name)),
    CONSTRAINT chk_process_procedure_objects_description_localized
        CHECK (description IS NULL OR app.is_localized_text(description))
);

COMMENT ON TABLE app.process_procedure_objects IS
    'Procedure object registry, one row per namespace and object_name. Rows are written only by init scripts and migrations. ON DELETE RESTRICT from app.process_procedures protects an object that still has procedures. A namespace that still has objects is protected by ON DELETE RESTRICT on namespace_key.';
COMMENT ON COLUMN app.process_procedure_objects.object_key IS
    'Primary key. Must equal namespace_key concatenated with a dot and object_name.';
COMMENT ON COLUMN app.process_procedure_objects.namespace_key IS
    'Owning namespace. Foreign key to app.process_procedure_namespaces, ON DELETE RESTRICT. Indexed by idx_process_procedure_objects_namespace.';
COMMENT ON COLUMN app.process_procedure_objects.object_name IS
    'Name within the namespace. Must match ^[a-z][a-z0-9_]*$. Unique together with namespace_key.';
COMMENT ON COLUMN app.process_procedure_objects.name IS
    'Localized display name. JSON object with required non-empty english and optional russian string. No other keys. Checked by app.is_localized_text.';
COMMENT ON COLUMN app.process_procedure_objects.description IS
    'Localized description of the object. NULL, or LocalizedText with required non-empty english and optional russian. Plain text.';
COMMENT ON COLUMN app.process_procedure_objects.is_system IS
    'True for platform-seeded objects.';
COMMENT ON COLUMN app.process_procedure_objects.created_at IS
    'Time the row was inserted by an init script or a migration.';

CREATE TABLE IF NOT EXISTS app.process_procedures (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    procedure_key  VARCHAR(150) NOT NULL,
    object_key     VARCHAR(100) NOT NULL,
    action         VARCHAR(50) NOT NULL,
    activity_type  VARCHAR(20) NOT NULL,
    payload_format VARCHAR(20) NOT NULL DEFAULT 'json',
    schema_version INTEGER NOT NULL DEFAULT 1,
    name           JSONB NOT NULL,
    description    JSONB NOT NULL,
    input_schema   JSONB NOT NULL DEFAULT '[]'::jsonb,
    output_schema  JSONB NOT NULL DEFAULT '[]'::jsonb,
    is_system      BOOLEAN NOT NULL DEFAULT true,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_process_procedures_object_key
        FOREIGN KEY (object_key) REFERENCES app.process_procedure_objects (object_key) ON DELETE RESTRICT,
    CONSTRAINT uq_process_procedures_key
        UNIQUE (procedure_key),
    CONSTRAINT uq_process_procedures_object_action_type
        UNIQUE (object_key, action, activity_type),
    CONSTRAINT chk_process_procedures_action_format
        CHECK (action ~ '^[a-z][a-z0-9_]*$'),
    CONSTRAINT chk_process_procedures_key_match
        CHECK (procedure_key = object_key || '.' || action),
    CONSTRAINT chk_process_procedures_activity_type
        CHECK (activity_type IN ('system', 'manual', 'external')),
    CONSTRAINT chk_process_procedures_payload_format
        CHECK (payload_format IN ('json', 'xml', 'csv', 'hl7v2', 'fhir', 'edi')),
    CONSTRAINT chk_process_procedures_schema_version_min
        CHECK (schema_version >= 1),
    CONSTRAINT chk_process_procedures_name_localized
        CHECK (app.is_localized_text(name)),
    CONSTRAINT chk_process_procedures_description_localized
        CHECK (app.is_localized_text(description)),
    CONSTRAINT chk_process_procedures_input_schema_array
        CHECK (jsonb_typeof(input_schema) = 'array'),
    CONSTRAINT chk_process_procedures_output_schema_array
        CHECK (jsonb_typeof(output_schema) = 'array')
);

COMMENT ON TABLE app.process_procedures IS
    'Unified procedure catalog for system, manual, and external activities. procedure_key is object_key, a dot, and action. Rows are written only by init scripts and migrations. System rows (is_system = true) are protected from deletion by tgr_process_procedures_prevent_system_delete.';
COMMENT ON COLUMN app.process_procedures.id IS
    'Row UUID. Assigned by gen_random_uuid() on INSERT or seeded deterministically.';
COMMENT ON COLUMN app.process_procedures.procedure_key IS
    'Stable key in namespace.object.action form (for example work.service_request.create). Unique. Must equal object_key concatenated with a dot and action.';
COMMENT ON COLUMN app.process_procedures.object_key IS
    'Object this procedure belongs to. Foreign key to app.process_procedure_objects, ON DELETE RESTRICT. Indexed by idx_process_procedures_object_key.';
COMMENT ON COLUMN app.process_procedures.action IS
    'Action segment. Must match ^[a-z][a-z0-9_]*$. Unique together with object_key and activity_type.';
COMMENT ON COLUMN app.process_procedures.activity_type IS
    'Which activity may call this procedure: system, manual, or external. Indexed by idx_process_procedures_activity_type.';
COMMENT ON COLUMN app.process_procedures.payload_format IS
    'Wire format of the procedure payload: json, xml, csv, hl7v2, fhir, or edi. Default json.';
COMMENT ON COLUMN app.process_procedures.schema_version IS
    'Schema version of input_schema and output_schema. Integer >= 1. Default 1.';
COMMENT ON COLUMN app.process_procedures.name IS
    'Localized display name of the procedure action. english is required and non-empty; russian is optional.';
COMMENT ON COLUMN app.process_procedures.description IS
    'Localized description of what the procedure does, its inputs, and its outputs. english is required and non-empty; russian is optional.';
COMMENT ON COLUMN app.process_procedures.input_schema IS
    'JSON array of input attribute descriptors ({key, type, required, source, enum?, label, description}).';
COMMENT ON COLUMN app.process_procedures.output_schema IS
    'JSON array of output variable descriptors ({key, type, enum?, label, description, example}) written to context.activities.<elementId>.';
COMMENT ON COLUMN app.process_procedures.is_system IS
    'True for platform-seeded procedures that cannot be deleted.';
COMMENT ON COLUMN app.process_procedures.created_at IS
    'Row creation timestamp.';

CREATE OR REPLACE FUNCTION app.prevent_process_procedure_deletion()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF OLD.is_system = true THEN
        RAISE EXCEPTION 'system procedure % cannot be deleted', OLD.procedure_key
            USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
END;
$$;

COMMENT ON FUNCTION app.prevent_process_procedure_deletion() IS
    'BEFORE DELETE row guard for app.process_procedures. Raises object_not_in_prerequisite_state (55000) when is_system is true.';

DROP TRIGGER IF EXISTS tgr_process_procedures_prevent_system_delete ON app.process_procedures;
CREATE TRIGGER tgr_process_procedures_prevent_system_delete
BEFORE DELETE ON app.process_procedures
FOR EACH ROW EXECUTE FUNCTION app.prevent_process_procedure_deletion();

-- Event-start idempotency: at most one instance per process and start_event_id.
CREATE UNIQUE INDEX IF NOT EXISTS uq_process_instances_start_event
    ON app.process_instances USING btree (process_id, start_event_id)
    WHERE start_event_id IS NOT NULL;

-- Schedule start lookups by process and start element.
CREATE INDEX IF NOT EXISTS idx_process_instances_schedule
    ON app.process_instances USING btree (process_id, start_element_id, started_at DESC)
    WHERE start_trigger_type = 'schedule';

-- Subject lookup: instances linked to a business entity (e.g. service_order, service_request).
CREATE INDEX IF NOT EXISTS idx_process_instances_subject
    ON app.process_instances USING btree (subject_type, subject_id)
    WHERE subject_id IS NOT NULL;

-- Process procedures catalog foreign-key and activity_type lookups.
CREATE INDEX IF NOT EXISTS idx_process_procedure_objects_namespace
    ON app.process_procedure_objects USING btree (namespace_key);

CREATE INDEX IF NOT EXISTS idx_process_procedures_object_key
    ON app.process_procedures USING btree (object_key);

CREATE INDEX IF NOT EXISTS idx_process_procedures_activity_type
    ON app.process_procedures USING btree (activity_type);

