ON CONFLICT (procedure_key) DO UPDATE SET
    object_key = EXCLUDED.object_key,
    action = EXCLUDED.action,
    activity_type = EXCLUDED.activity_type,
    payload_format = EXCLUDED.payload_format,
    schema_version = EXCLUDED.schema_version,
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    input_schema = EXCLUDED.input_schema,
    output_schema = EXCLUDED.output_schema,
    is_system = EXCLUDED.is_system;

-- value is set only on insert. Conflict refreshes product-owned columns and does not write value.
INSERT INTO app.app_settings (
    section_path, setting_name, environment, value, validation_schema, default_value, description, is_public
) VALUES (
    'AdminApp.Practices',
    'time_tracking.require_actual_on_close',
    'all',
    'false'::jsonb,
    '{"type":"boolean"}'::jsonb,
    'false'::jsonb,
    'Require actual work time to be filled before resolving or closing a service request or completing a manual task as succeeded.',
    false
)
ON CONFLICT (section_path, setting_name, environment) DO UPDATE SET
    validation_schema = EXCLUDED.validation_schema,
    default_value = EXCLUDED.default_value,
    description = EXCLUDED.description,
    is_public = EXCLUDED.is_public,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO app.permissions (permission_key, module, description) VALUES
('adminCatalog:sections:manage_acl:all', 'adminCatalog', 'Manage access control (visibility) for all catalog sections')
ON CONFLICT (permission_key) DO NOTHING;

DO $$
DECLARE
    sys_user_id UUID;
BEGIN
    SELECT user_id INTO sys_user_id FROM app.users WHERE username = 'admin' LIMIT 1;
    IF sys_user_id IS NULL THEN
        RAISE EXCEPTION 'Authorization seed failed: system admin user (username=admin) not found.';
    END IF;

    INSERT INTO app.group_permissions (group_id, permission_key, granted_by)
    SELECT g.group_id, 'adminCatalog:sections:manage_acl:all', sys_user_id
    FROM app.groups g
    WHERE g.group_name IN ('role.adminCatalog.admin', 'role.adminCatalog.editor', 'sysadmins')
    ON CONFLICT DO NOTHING;
END $$;

INSERT INTO app.app_settings (
    section_path, setting_name, environment, value, validation_schema, default_value, description, is_public
) VALUES (
    'AdminApp.Catalog',
    'allow.public.access',
    'all',
    'false'::jsonb,
    '{"type":"boolean"}'::jsonb,
    'false'::jsonb,
    'When true the public (no login required) access level can be enabled on catalog sections. Turning this off downgrades any public catalog sections to all registered users.',
    true
)
ON CONFLICT (section_path, setting_name, environment) DO UPDATE SET
    validation_schema = EXCLUDED.validation_schema,
    default_value = EXCLUDED.default_value,
    description = EXCLUDED.description,
    is_public = EXCLUDED.is_public,
    updated_at = CURRENT_TIMESTAMP;

-- Existing catalog sections without a read ACL default to registered users.
INSERT INTO app.entity_acl (entity_type, entity_id, action, audience, created_by)
SELECT 'catalog_section', cs.id, 'read', 'registered', COALESCE(cs.owner, cs.created_by)
FROM app.catalog_sections cs
ON CONFLICT (entity_type, entity_id, action) DO NOTHING;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'chk_users_system_no_expires_at'
          AND conrelid = 'app.users'::regclass
    ) THEN
        ALTER TABLE app.users
            ADD CONSTRAINT chk_users_system_no_expires_at
            CHECK (account_type <> 'system'::app.account_type OR expires_at IS NULL);
    END IF;
END $$;

COMMENT ON COLUMN app.users.expires_at IS 'Optional account expiration for standard and bot principals. NULL means no expiration. System principals must not set it (chk_users_system_no_expires_at).';

DO $$
BEGIN
    PERFORM app.set_migration_output_summary(
        'm_0.27.3',
        'Added work time tracking and WBS/Gantt attributes to service requests and activities, updated process procedures and event schemas, seeded AdminApp.Practices time_tracking.require_actual_on_close, seeded adminCatalog:sections:manage_acl:all, seeded AdminApp.Catalog allow.public.access, and backfilled missing catalog section read ACLs to registered, and system accounts cannot have expires_at, and published the HELP KB BPMN library article and the HELP KB events library article, replaced the denormalized process procedure catalogs with the normalized procedure catalog, and added process instance start columns and process token wait columns'
    );
END $$;

UPDATE app.event_types
SET summary = '{"english":"A user placed an order for one of the services available in the catalog.","russian":"Пользователь оформил заказ на одну из услуг, доступных в каталоге."}'::jsonb
WHERE event_type = 'catalog.service_order.submitted';

